responses:
{
  "summary": "Added a crew_location enum quality so the story can track whether the crew is on the street, in the lobby, or in the vault.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "crew_location",
        "type": "enum",
        "source": "extractor",
        "values": [
          "street",
          "lobby",
          "vault"
        ],
        "rubric": "Where is the crew right now? Answer street, lobby, or vault based on the current scene.",
        "read_as": "choice"
      }
    }
  ]
}

{
  "summary": "Added an intermediate checkpoint 'lobby' between 'start' and 'vault' where the crew cracks the lobby door. Removed the direct start->vault transition and replaced it with start->lobby and lobby->vault (gated on has_key).",
  "ops": [
    {
      "kind": "addCheckpoint",
      "checkpoint": {
        "id": "lobby",
        "name": "Cracking the Lobby Door",
        "objective": "Get through the lobby door without tripping the alarm.",
        "type": "intermediate",
        "tension_target": "tense"
      }
    },
    {
      "kind": "removeTransition",
      "ref": {
        "from": "start",
        "to": "vault"
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "start",
        "to": "lobby",
        "priority": 1,
        "gate": {
          "q": "has_key",
          "op": "in",
          "v": [true, false]
        }
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "lobby",
        "to": "vault",
        "priority": 1,
        "gate": {
          "q": "has_key",
          "op": "==",
          "v": true
        }
      }
    }
  ]
}

{
  "summary": "Added an intermediate checkpoint for cracking the lobby door between casing the bank and reaching the vault.",
  "ops": [
    {
      "kind": "addCheckpoint",
      "checkpoint": {
        "id": "lobby",
        "name": "Cracking the Lobby Door",
        "objective": "Crack the bank's lobby door and slip the crew inside.",
        "type": "intermediate",
        "tension_target": "tense",
        "guidance": "The bank is closed; the crew must work the lobby lock without tripping alarms or drawing the night guard."
      }
    }
  ]
}

{
  "summary": "Added an intermediate checkpoint 'The Sun Door' between the Ruins and the Inner Chamber, where the party must solve the sun door puzzle.",
  "ops": [
    {
      "kind": "addCheckpoint",
      "checkpoint": {
        "id": "sun_door",
        "name": "The Sun Door",
        "objective": "Solve the sun door puzzle to open the way into the inner chamber.",
        "type": "intermediate",
        "tension_target": "tense",
        "guidance": "The door is sealed by a mechanism of light and shadow; the party must align the sunbeams to unlock it."
      }
    }
  ]
}

{
  "summary": "Added Vex as the crew's lockpick, nervous but brilliant, and set the story to require her card.",
  "ops": [
    {
      "kind": "addRosterMember",
      "member": {
        "id": "vex",
        "name": "Vex",
        "role": "The crew's lockpick; opens what should stay shut.",
        "drive": "Prove her brilliance without letting her nerves crack the job."
      }
    },
    {
      "kind": "setRequirements",
      "requirements": {
        "members": ["Vex"]
      }
    }
  ]
}

{
  "summary": "Creates Vex, the Vault Job Lore lorebook with entries for the bank, vault, and key, and the group The Vault Job Crew.",
  "ops": [
    {
      "kind": "createCharacterCard",
      "name": "Vex",
      "description": "Vex is the crew's lockpick, a wiry woman with nimble fingers and a dry wit. She's casing the bank with you, eyeing the vault's lock.",
      "role": "The crew's lockpick",
      "personality": "Cynical, precise, loyal to the crew.",
      "scenario": "Casing the city bank before the heist.",
      "first_mes": "Vex leans against the marble column, flipping a pick between her fingers. 'So, boss. The vault's a Delacroix 12. I can crack it, but it'll take time we don't have. You get that key yet?'",
      "tags": ["thief", "lockpick", "crew"]
    },
    {
      "kind": "createStoryLorebook",
      "name": "Vault Job Lore"
    },
    {
      "kind": "upsertLorebookEntry",
      "lorebook": "Vault Job Lore",
      "comment": "The City Bank",
      "keys": ["bank", "city bank"],
      "content": "The City Bank is a grand marble building in the financial district. It houses the city's largest vault, the Delacroix 12.",
      "constant": false
    },
    {
      "kind": "upsertLorebookEntry",
      "lorebook": "Vault Job Lore",
      "comment": "The Vault",
      "keys": ["vault", "Delacroix 12"],
      "content": "The Delacroix 12 is a high-security vault. It requires a special key to open without triggering the alarm.",
      "constant": false
    },
    {
      "kind": "upsertLorebookEntry",
      "lorebook": "Vault Job Lore",
      "comment": "The Vault Key",
      "keys": ["key", "vault key"],
      "content": "The vault key is held by the bank manager, Mr. Holloway. He keeps it on his person at all times.",
      "constant": false
    },
    {
      "kind": "createGroup",
      "name": "The Vault Job Crew",
      "members": ["Vex"]
    }
  ]
}

{
  "summary": "Added the final anchor checkpoint 'The Wreck', where the crew abandons the drifting ship carrying the captain's log.",
  "ops": [
    {
      "kind": "addCheckpoint",
      "checkpoint": {
        "id": "wreck",
        "name": "The Wreck",
        "objective": "Abandon the drifting ship with the captain's log.",
        "type": "anchor",
        "tension_target": "peak"
      }
    }
  ]
}

{
  "summary": "Set The Crypt checkpoint snapshot so door_open is true when the story reaches it.",
  "ops": [
    {
      "kind": "setCheckpointSnapshot",
      "id": "crypt",
      "snapshot": {
        "door_open": true
      }
    }
  ]
}
